    ["Follow ^Akama^ into the next area. Talk to him to start the final battle against ^Illidan Stormrage^."] = "Siga ^Akama^ até a próxima área. Fale com ele para iniciar a batalha final contra ^Illidan Stormrage^.",
    ["Follow Path Ahead"] = "Siga o caminho em frente",
    ["Follow path to Lucifron"] = "Siga o caminho até Lucifron",
