    ["Follow the foundry floor to ^Prototype Pantheon^."] = "Siga o foundry floor para ^Prototype Pantheon^.",
    ["Follow the map from the entrance to ^The Tarragrue^."] = "Siga o mapa da entrada para ^The Tarragrue^.",
    ["Follow the mineshaft into the next room. After a lengthy dialog, speak to ^Norushen^ to start the encounter."] = "Siga o mineshaft para dentro da próxima sala. Depois um longo diálogo, fale com ^Norushen^ para iniciar o encontro.",
    ["Follow the path all the way back to find ^Il'gynoth, Corruption Reborn^."] = "Siga o caminho por todo o caminho de volta para encontre ^Il'gynoth, Corruption Reborn^.",
    ["Follow the path all the way back to meet the ^Council of Dreams^. Click each of the illusions to start the fight."] = "Siga todo o caminho de volta até ^Council of Dreams^. Clique em cada ilusão para iniciar a luta.",
    ["Follow the path and kill ^Braekkas^ to open the wall. Continue on to find ^The Primal Council^."] = "Siga o caminho e mate ^Braekkas^ para abrir o parede. Continue em para encontrar ^The Primal Council^.",
    ["Follow the path around to ^Hellfire High Council^."] = "Siga o caminho ao redor para ^Hellfire High Council^.",
    ["Follow the path back out to the main courtyard, and make your way to the ^Captain's Quarters^ entrance on the southwest corner of the map. Inside the ^Captain's Quarters^, take your first right to go up a short stairwell."] = "Siga o caminho de volta ao pátio principal e vá até a entrada de ^Captain's Quarters^ no canto sudoeste do mapa. Dentro de ^Captain's Quarters^, pegue a primeira à direita e suba uma escadaria curta.",
    ["Follow the path down to ^Skolex^. Kill the trash to spawn the boss."] = "Siga o caminho para baixo para ^Skolex^. Elimine os inimigos para fazer aparecer o chefe.",
    ["Follow the path south and continue on to ^The Illidari Council^."] = "Siga o caminho ao sul e continue até ^The Illidari Council^.",
    ["Follow the path through ^The Endless Foundry^, killing the trash on the way to ^Lihuvim^."] = "Siga o caminho através de ^The Endless Foundry^, eliminando os inimigos no caminho para ^Lihuvim^.",
    ["Follow the path through ^The Grand Design^, killing trash on the way to ^Lords of Dread^."] = "Siga o caminho através de ^The Grand Design^, eliminando inimigos no caminho para ^Lords of Dread^.",
    ["Follow the path through the next area until you reach ^Teron Gorefiend^."] = "Siga o caminho pela próxima área até chegar a ^Teron Gorefiend^.",
    ["Follow the path to reach the ^Ascendant Council^."] = "Siga o caminho para chegar ao ^Ascendant Council^.",
    ["Follow the path to the boss area, and clear the trash to spawn ^Volcoross^."] = "Siga o caminho para o chefe área, e elimine o inimigos para fazer aparecer ^Volcoross^.",
    ["Follow the path to the final map exit labeled ^N'Zoth^. Kill adds on the bridge to spawn a portal at the end."] = "Siga até a saída final do mapa marcada como ^N'Zoth^. Mate adversários na ponte para fazer um portal aparecer no fim.",
    ["Follow the path to the map exit labeled ^The Hive^."] = "Siga o caminho para a saída do mapa marcada como ^The Hive^.",
    ["Follow the path up and to the left to reach ^Tectus^. Kill the (3) rock golems to spawn the boss."] = "Siga o caminho para cima e à esquerda para chegar a ^Tectus^. Mate o (3) rock golems para fazer aparecer o chefe.",
    ["Follow the path up the stairs and around to the map exit labeled ^Halls of Opulence^. Jump in the hole at the end of the path."] = "Suba pelas escadas e siga ao redor até a saída do mapa marcada como ^Halls of Opulence^. Salte no buraco no fim do caminho.",
    ["Follow the path up to ^Broodkeeper Diurna^."] = "Siga o caminho para cima para ^Broodkeeper Diurna^.",
    ["Follow the path. Once you reach the boss room, kill the final trash pack and talk to ^Lorewalker Cho^ to trigger the boss fight with ^Elegon^."] = "Siga o caminho. Ao chegar à sala do chefe, mate os últimos inimigos pack e Fale com ^Lorewalker Cho^ para ative o chefe luta com ^Elegon^.",
    ["Font of Power"] = "Fonte de Poder",
    ["For the knockback, position yourself between the boss and a tornado."] = "Para o repelão, posicione-se entre o chefe e um tornado.",
    ["Formation Seed"] = "Semente da Formação",
    ["Forward then left to Ignis"] = "Forward depois esquerda para Ignis",
    ["Forward to Imonar"] = "Avance até Imonar",
    ["From ^The Primal Convergence^, follow the path to the entrance labeled ^Iceskitter Hollow^."] = "De ^The Primal Convergence^, siga o caminho até a entrada marcada como ^Iceskitter Hollow^.",
    ["From ^Wellspring Atrium^, take the final remaining exit labeled ^Throne of the Firelord^. Click on the ^Formation Seed^ to construct a bridge to the next area."] = "De ^Wellspring Atrium^, pegue o final remaining saída marcada como ^Throne of the Firelord^. Clique no ^Formation Seed^ para construct um ponte até o próxima área.",
    ["From the bottom of the stairs, take a hard left and descend into the tunnels."] = "No pé das escadas, vire bem à esquerda e desça para os túneis.",
    ["From the top of the elevator, proceed ahead up the ramp to find the ^Antoran High Command^."] = "De o topo do elevador, siga em frente pela rampa acima para encontrar o ^Antoran High Command^.",
    ["From the top of the stairs, take your first right. Travel east down the hallway until you reach ^Maiden of Virtue^."] = "Do topo das escadas, pegue a primeira à direita. Siga a leste pelo corredor até chegar a ^Maiden of Virtue^.",
    ["Fyrakk additionally drops {item}, an omnitoken that exchanges for any tier slot. Not tracked here."] = "Fyrakk também deixa cair {item}, uma ficha universal que pode ser trocada por qualquer espaço de conjunto. Não é rastreada aqui.",
    ["Galewind Crag then Upward Draft"] = "Penhasco Ventania depois Corrente Ascendente",
    ["Garrosh also drops {tokens}, which are omnitokens that allow you to purchase any Tier 16 set piece of matching quality. Not tracked here."] = "Garrosh também deixa {tokens}, fichas universais que permitem comprar qualquer peça de conjunto do Tier 16 de qualidade correspondente. Não rastreado aqui.",
    ["Gauntlet then Dragons"] = "Gauntlet depois Dragons",
    ["General Draven"] = "General Draven",
    ["Go Down Elevator"] = "Desça pelo elevador",
    ["Go down elevator"] = "Desça pelo elevador",
    ["Go Here"] = "Vá até aqui",
